 public sealed class FrameStripContext {public string File;public VideoInfo Info;public AnalysisResult Result;public double Time;public List<double> WindowTimes;public int WindowFirstLabel,WindowCenterOffset;public bool Exact {get{return Result!=null&&!Result.EstimatedTimes&&Result.Times.Count==Result.FrameCount;}}public int Count {get{return Result!=null?Result.FrameCount:Math.Max(1,(int)Math.Round(Info.Duration*Info.Fps));}}public int Center {get{if(WindowTimes!=null)return WindowFirstLabel+WindowCenterOffset;if(Exact){int n=Result.Times.BinarySearch(Time);return Math.Max(0,Math.Min(Count-1,n>=0?n:~n-1));}return Math.Max(0,Math.Min(Count-1,(int)Math.Round(Time/Math.Max(.000001,1/Info.Fps))));}}public int First {get{return WindowTimes!=null?WindowFirstLabel:Math.Max(0,Center-15);}}public int Last {get{return WindowTimes!=null?WindowFirstLabel+WindowTimes.Count-1:Math.Min(Count-1,Center+15);}}public double At(int index){if(WindowTimes!=null)return WindowTimes[Math.Max(0,Math.Min(WindowTimes.Count-1,index-WindowFirstLabel))];return Exact?Result.Times[index]:index/Info.Fps;}}
 public sealed class FrameStill {public int Index;public double Time;public byte[] Bytes;}
 public sealed class FrameStripSnapshot {public FrameStripContext Context;public string Fingerprint;public List<FrameStill> Frames=new List<FrameStill>();}
 public static class FrameStripExtractor {
  public static string Fingerprint(string file){var info=new FileInfo(file);return info.Length+"|"+info.LastWriteTimeUtc.Ticks+"|"+Shell.Fingerprint(file);}
  static void Extract(FrameStripContext context,string directory,bool original,CancellationToken token){Directory.CreateDirectory(directory);string filter=original?"":" -vf scale=256:144:force_original_aspect_ratio=decrease";string args="-y -hide_banner -nostdin -loglevel error -threads 1 -filter_threads 1 -ss "+Util.Num(Math.Max(0,context.At(context.First)-.00001))+" -i "+Util.Q(context.File)+" -map 0:V:0 -an -sn -dn -frames:v "+(context.Last-context.First+1)+" -vsync 0"+filter+" -c:v png -threads 1 -start_number "+(context.First+1)+" "+Util.Q(Path.Combine(directory,"frame-%06d.png"));Diagnostics.Log("filmstrip.extract",new {context.File,FirstFrame=context.First+1,LastFrame=context.Last+1,CenterFrame=context.Center+1,Original=original,context.Exact,Output=directory});using(var process=Detector.Start(args))using(token.Register(()=>Detector.Kill(process))){var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();process.WaitForExit();string stderr=error.GetAwaiter().GetResult();token.ThrowIfCancellationRequested();Diagnostics.Log("filmstrip.ffmpeg",new {Exit=process.ExitCode,Output=stderr});if(process.ExitCode!=0)throw new IOException("静帧读取失败："+stderr);}if(Directory.GetFiles(directory,"frame-*.png").Length==0)throw new IOException("没有读取到可用静帧。");}
  public static FrameStripSnapshot Load(FrameStripContext context,CancellationToken token){if(!context.Exact)return LoadAroundTime(context,token);string directory=Path.Combine(Path.GetTempPath(),"FrameScout-frames-"+Guid.NewGuid().ToString("N"));var snapshot=new FrameStripSnapshot{Context=context,Fingerprint=Fingerprint(context.File)};try{Extract(context,directory,false,token);foreach(var file in Directory.GetFiles(directory,"frame-*.png").OrderBy(x=>x,StringComparer.Ordinal)){token.ThrowIfCancellationRequested();int index=int.Parse(Path.GetFileNameWithoutExtension(file).Substring(6))-1;snapshot.Frames.Add(new FrameStill{Index=index,Time=context.At(index),Bytes=File.ReadAllBytes(file)});}if(Fingerprint(context.File)!=snapshot.Fingerprint)throw new IOException("视频读取期间发生替换，请重新悬停刷新。");return snapshot;}finally{try{string full=Path.GetFullPath(directory),root=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar);if(Path.GetDirectoryName(full)==root&&Path.GetFileName(full).StartsWith("FrameScout-frames-",StringComparison.Ordinal)&&Directory.Exists(full))Directory.Delete(full,true);}catch{}}}
  static void Cleanup(string directory){try{string full=Path.GetFullPath(directory),root=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar);if(Path.GetDirectoryName(full)==root&&Path.GetFileName(full).StartsWith("FrameScout-frames-",StringComparison.Ordinal)&&Directory.Exists(full))Directory.Delete(full,true);}catch{}}
  static FrameStripSnapshot LoadAroundTime(FrameStripContext context,CancellationToken token){string directory=Path.Combine(Path.GetTempPath(),"FrameScout-frames-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);var snapshot=new FrameStripSnapshot{Context=context,Fingerprint=Fingerprint(context.File)};int approximateCenter=context.Center;double margin=Math.Max(2,32/Math.Max(.1,context.Info.Fps));try{for(int attempt=0;attempt<6;attempt++){token.ThrowIfCancellationRequested();string folder=Path.Combine(directory,attempt.ToString());Directory.CreateDirectory(folder);double seek=Math.Max(0,context.Time-margin),end=context.Time+margin;var stamps=new List<double>();string args="-y -hide_banner -nostdin -loglevel info -threads 1 -filter_threads 1 -ss "+Util.Num(Math.Max(0,seek-.00001))+" -i "+Util.Q(context.File)+" -map 0:V:0 -an -sn -dn -t "+Util.Num(end-seek)+" -vf scale=256:144:force_original_aspect_ratio=decrease,showinfo -frames:v 5000 -vsync 0 -c:v png -threads 1 -start_number 0 "+Util.Q(Path.Combine(folder,"window-%06d.png"));using(var process=Detector.Start(args))using(token.Register(()=>Detector.Kill(process))){process.ErrorDataReceived+=(s,e)=>{if(e.Data==null)return;var match=Regex.Match(e.Data,@"n:\s*\d+\s+pts:.*?pts_time:([\d.Ee+\-]+)");if(match.Success){double value;if(double.TryParse(match.Groups[1].Value,System.Globalization.NumberStyles.Float,Util.CI,out value))lock(stamps)stamps.Add(Math.Max(0,seek-.00001)+value);}else if(!e.Data.Contains("showinfo"))Diagnostics.Log("filmstrip.decode",new{Message=e.Data});};process.BeginErrorReadLine();var output=process.StandardOutput.ReadToEndAsync();process.WaitForExit();token.ThrowIfCancellationRequested();if(process.ExitCode!=0)throw new IOException("当前时间点的静帧读取失败。");}var files=Directory.GetFiles(folder,"window-*.png").OrderBy(x=>x,StringComparer.Ordinal).ToArray();if(files.Length==0||stamps.Count<files.Length)throw new IOException("静帧时间戳不完整，请先检测视频后重试。");stamps=stamps.Take(files.Length).ToList();if(stamps[0]>context.Time+.0001&&seek<=.0001)throw new IOException("当前时间之前没有可显示的画面。");int center=0;for(int i=0;i<stamps.Count;i++){if(stamps[i]<=context.Time+.0001)center=i;else break;}bool missingBefore=center<15&&seek>.0001,missingAfter=files.Length-1-center<15&&end<context.Info.Duration-.001;if((missingBefore||missingAfter)&&attempt<5){margin*=2;continue;}int first=Math.Max(0,center-15),last=Math.Min(files.Length-1,center+15);context.WindowFirstLabel=seek<=.0001?first:Math.Max(0,approximateCenter-(center-first));context.WindowCenterOffset=center-first;context.WindowTimes=stamps.Skip(first).Take(last-first+1).ToList();for(int i=first;i<=last;i++)snapshot.Frames.Add(new FrameStill{Index=context.WindowFirstLabel+i-first,Time=stamps[i],Bytes=File.ReadAllBytes(files[i])});if(Fingerprint(context.File)!=snapshot.Fingerprint)throw new IOException("视频读取期间发生替换，请重新悬停刷新。");Diagnostics.Log("filmstrip.timestamp_window",new{context.File,RequestedSeconds=context.Time,ActualCenterSeconds=stamps[center],Count=snapshot.Frames.Count,GlobalFrameNumbersEstimated=true});return snapshot;}throw new IOException("无法形成完整的当前帧窗口。");}finally{Cleanup(directory);}}
  public static string Save(FrameStripSnapshot snapshot,string parent,CancellationToken token){if(Fingerprint(snapshot.Context.File)!=snapshot.Fingerprint)throw new IOException("视频已替换，请重新悬停加载后再保存。");string name=Path.GetFileNameWithoutExtension(snapshot.Context.File);foreach(char c in Path.GetInvalidFileNameChars())name=name.Replace(c,'_');name=name.Substring(0,Math.Min(name.Length,55));string directory=Path.Combine(Path.GetFullPath(parent),name+"_第"+(snapshot.Context.Center+1)+"帧_前后15帧_"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));Directory.CreateDirectory(directory);try{Extract(snapshot.Context,directory,true,token);if(Fingerprint(snapshot.Context.File)!=snapshot.Fingerprint)throw new IOException("保存期间视频发生替换，输出需要重新核对。");var files=Directory.GetFiles(directory,"frame-*.png").OrderBy(x=>x,StringComparer.Ordinal).Select(file=>new {File=Path.GetFileName(file),FrameNumber=int.Parse(Path.GetFileNameWithoutExtension(file).Substring(6)),Seconds=snapshot.Context.At(int.Parse(Path.GetFileNameWithoutExtension(file).Substring(6))-1)}).ToArray();File.WriteAllText(Path.Combine(directory,"静帧说明.json"),Util.Json().Serialize(new {Video=snapshot.Context.File,snapshot.Fingerprint,CenterFrame=snapshot.Context.Center+1,FirstFrame=snapshot.Context.First+1,LastFrame=snapshot.Context.Last+1,ExactFrameNumbers=snapshot.Context.Exact,Format="原尺寸PNG，帧号从1开始",Files=files}),new UTF8Encoding(false));Diagnostics.Log("filmstrip.saved",new {Directory=directory,Count=files.Length});return directory;}catch(Exception ex){try{File.WriteAllText(Path.Combine(directory,"保存未完成.txt"),ex.Message,new UTF8Encoding(true));}catch{}throw;}}
 }
 public sealed class FrameStripPreview {
  readonly Button trigger;readonly Func<FrameStripContext> capture;readonly Action<double> locate;readonly Action<string> status;readonly DispatcherTimer openTimer,closeTimer;Window window;CancellationTokenSource loading,saving;bool pinned,busy,opening;int generation,fadeGeneration;FrameStripSnapshot snapshot;string cacheKey;TextBlock message;StackPanel strip;ScrollViewer scroll;Button pin,save;string lastFolder;
  [StructLayout(LayoutKind.Sequential)]struct RectI {public int Left,Top,Right,Bottom;}
  [DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr handle,out RectI rectangle);[DllImport("user32.dll")]static extern bool SetWindowPos(IntPtr handle,IntPtr after,int x,int y,int width,int height,uint flags);
  public FrameStripPreview(Button trigger,Func<FrameStripContext> capture,Action<double> locate,Action<string> status){this.trigger=trigger;this.capture=capture;this.locate=locate;this.status=status;openTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(220)};closeTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(250)};openTimer.Tick+=async(s,e)=>{openTimer.Stop();if(trigger.IsMouseOver)await Show(false);};closeTimer.Tick+=(s,e)=>{closeTimer.Stop();if(!pinned&&!busy&&!trigger.IsMouseOver&&(window==null||!window.IsMouseOver))FadeOut();};trigger.MouseEnter+=(s,e)=>{closeTimer.Stop();if(window==null)openTimer.Start();else FadeIn();};trigger.MouseLeave+=(s,e)=>{openTimer.Stop();closeTimer.Start();};trigger.Click+=async(s,e)=>await Show(true);trigger.Unloaded+=(s,e)=>Close();}
  public bool IsOpen {get{return window!=null;}}public FrameStripSnapshot Snapshot {get{return snapshot;}}
  public async Task Show(bool pinOpen){openTimer.Stop();closeTimer.Stop();if(opening)return;if(window!=null){if(pinOpen){pinned=true;pin.Content="已固定";}FadeIn();return;}int ticket=++generation;opening=true;FrameStripContext context;try{context=capture();if(context==null||!File.Exists(context.File)){opening=false;status("请先选择可读取的视频。");return;}if(context.Info==null)context.Info=await Task.Run(()=>Detector.Probe(context.File,CancellationToken.None));}catch(Exception ex){if(ticket!=generation)return;opening=false;status("静帧预览未打开："+ex.Message);Diagnostics.Error("filmstrip.open_error",ex);return;}if(ticket!=generation)return;opening=false;if(!trigger.IsLoaded)return;var owner=Window.GetWindow(trigger);if(owner==null)return;pinned=pinOpen;var presentation=PresentationSource.FromVisual(trigger);double scale=presentation==null||presentation.CompositionTarget==null?1:presentation.CompositionTarget.TransformToDevice.M11;var screen=System.Windows.Forms.Screen.FromPoint(new System.Drawing.Point((int)trigger.PointToScreen(new Point()).X,(int)trigger.PointToScreen(new Point()).Y));double width=Math.Min(1600,screen.WorkingArea.Width/scale*.94);double cardWidth=Math.Max(48,Math.Min(100,(width-30)/31-4)),ratio=context.Info.Width>0&&context.Info.Height>0?(double)context.Info.Width/context.Info.Height:16.0/9;double imageHeight=Math.Max(28,Math.Min(100,cardWidth/ratio));window=FrameWindows.Dialog(owner,"前后15帧 · "+Path.GetFileName(context.File),(int)width,(int)(imageHeight+110));var currentWindow=window;window.WindowStyle=WindowStyle.ToolWindow;window.ResizeMode=ResizeMode.NoResize;window.ShowInTaskbar=false;window.ShowActivated=false;window.Opacity=0;window.Icon=owner.Icon;window.UseLayoutRounding=true;var grid=new Grid{Margin=new Thickness(8)};grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());var header=new DockPanel{Margin=new Thickness(0,0,0,7)};var tools=new StackPanel{Orientation=Orientation.Horizontal};pin=new Button{Content=pinned?"已固定":"固定",Padding=new Thickness(8,3,8,3),FontSize=11};pin.Click+=(s,e)=>{pinned=!pinned;pin.Content=pinned?"已固定":"固定";if(pinned)FadeIn();else closeTimer.Start();};save=new Button{Content="保存这些静帧…",Padding=new Thickness(8,3,8,3),FontSize=11,IsEnabled=false};save.Click+=async(s,e)=>await PickSave();tools.Children.Add(pin);tools.Children.Add(save);DockPanel.SetDock(tools,Dock.Right);header.Children.Add(tools);message=new TextBlock{Text="正在读取第"+(context.Center+1)+"帧前后各15帧…",FontSize=11,VerticalAlignment=VerticalAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis};header.Children.Add(message);grid.Children.Add(header);strip=new StackPanel{Orientation=Orientation.Horizontal};scroll=new ScrollViewer{Content=strip,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,1);grid.Children.Add(scroll);window.Content=grid;window.MouseEnter+=(s,e)=>{closeTimer.Stop();FadeIn();};window.MouseLeave+=(s,e)=>closeTimer.Start();window.Closed+=(s,e)=>{if(window==currentWindow){window=null;if(loading!=null)loading.Cancel();if(saving!=null)saving.Cancel();}};window.Show();Place(screen.WorkingArea);FadeIn();loading=new CancellationTokenSource();loading.CancelAfter(45000);var local=loading;try{string key=context.File+"|"+FrameStripExtractor.Fingerprint(context.File)+"|"+context.First+"|"+context.Last+"|"+context.Exact+"|"+context.Count+"|"+Util.Num(context.At(context.First))+"|"+Util.Num(context.At(context.Last));if(!context.Exact||snapshot==null||cacheKey!=key){var loaded=await Task.Run(()=>FrameStripExtractor.Load(context,local.Token));if(local.IsCancellationRequested||window!=currentWindow)return;snapshot=loaded;cacheKey=key;}else snapshot=new FrameStripSnapshot{Context=context,Fingerprint=snapshot.Fingerprint,Frames=snapshot.Frames};foreach(var frame in snapshot.Frames){var data=frame;var body=new StackPanel();body.Children.Add(new Image{Source=FrameWindows.Bitmap(data.Bytes),Width=cardWidth,Height=imageHeight,Stretch=Stretch.Uniform});body.Children.Add(new TextBlock{Text=(context.Exact?"":"约 ")+"第"+(data.Index+1)+"帧",FontSize=10,TextAlignment=TextAlignment.Center,Margin=new Thickness(0,4,0,0)});var button=new Button{Content=body,Padding=new Thickness(2),Margin=new Thickness(0,0,3,0),BorderBrush=data.Index==context.Center?Brushes.Orange:new SolidColorBrush(Color.FromRgb(64,81,106)),BorderThickness=new Thickness(data.Index==context.Center?2:1),ToolTip=Util.Time(data.Time)+" · 点击定位"};button.Click+=(s,e)=>{pinned=true;pin.Content="已固定";locate(data.Time);Diagnostics.Log("filmstrip.locate",new{context.File,Frame=data.Index+1,data.Time});};strip.Children.Add(button);}message.Text=Path.GetFileName(context.File)+" · 第"+(context.Center+1)+"帧 · "+snapshot.Frames.Count+"张"+(context.Exact?"":" · 帧号按帧率估算，检测后可获得实际帧号");message.ToolTip=context.File;save.IsEnabled=true;currentWindow.UpdateLayout();scroll.ScrollToHorizontalOffset(Math.Max(0,(context.Center-context.First)*(cardWidth+9)-scroll.ViewportWidth/2));Diagnostics.Log("filmstrip.opened",new{context.File,Frame=context.Center+1,Count=snapshot.Frames.Count,Exact=context.Exact});}catch(OperationCanceledException){}catch(Exception ex){if(window==currentWindow){message.Text="读取失败："+ex.Message;status(message.Text);}Diagnostics.Error("filmstrip.load_error",ex);}finally{if(loading==local)loading=null;local.Dispose();}}
  void FadeIn(){var target=window;if(target==null)return;fadeGeneration++;var animation=new DoubleAnimation(target.Opacity,1,TimeSpan.FromMilliseconds(180)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}};target.BeginAnimation(UIElement.OpacityProperty,animation);Diagnostics.Log("filmstrip.fade_in",new {trigger.Name});}
  void FadeOut(){var target=window;if(target==null){if(opening)Close();return;}if(pinned||busy)return;int ticket=++fadeGeneration;var animation=new DoubleAnimation(target.Opacity,0,TimeSpan.FromMilliseconds(170)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseIn}};animation.Completed+=(s,e)=>{if(window==target&&ticket==fadeGeneration&&!pinned&&!busy)Close();};target.BeginAnimation(UIElement.OpacityProperty,animation);Diagnostics.Log("filmstrip.fade_out",new {trigger.Name});}
  void Place(System.Drawing.Rectangle area){if(window==null)return;var handle=new WindowInteropHelper(window).Handle;RectI rect;if(!GetWindowRect(handle,out rect))return;var point=trigger.PointToScreen(new Point(0,0));int left=Math.Max(area.Left,Math.Min(area.Right-(rect.Right-rect.Left),(int)point.X-(rect.Right-rect.Left)/2)),top=Math.Max(area.Top,Math.Min(area.Bottom-(rect.Bottom-rect.Top),(int)point.Y-(rect.Bottom-rect.Top)-10));SetWindowPos(handle,IntPtr.Zero,left,top,0,0,0x1|0x4|0x10);}
  sealed class DialogOwner:System.Windows.Forms.IWin32Window{public IntPtr Handle{get;private set;}public DialogOwner(IntPtr value){Handle=value;}}
  async Task PickSave(){if(snapshot==null||busy)return;var savedSnapshot=snapshot;var saveWindow=window;busy=true;closeTimer.Stop();try{string folder=null;using(var dialog=new System.Windows.Forms.FolderBrowserDialog{Description="选择静帧保存位置（会创建独立子文件夹，原尺寸PNG）",SelectedPath=lastFolder??Environment.GetFolderPath(Environment.SpecialFolder.MyPictures)}){if(dialog.ShowDialog(new DialogOwner(new WindowInteropHelper(saveWindow).Handle))!=System.Windows.Forms.DialogResult.OK)return;folder=dialog.SelectedPath;}if(window!=saveWindow)return;lastFolder=folder;saving=new CancellationTokenSource();saving.CancelAfter(180000);var saveToken=saving.Token;save.IsEnabled=false;message.Text="正在保存原尺寸静帧…";var saved=await Task.Run(()=>FrameStripExtractor.Save(savedSnapshot,folder,saveToken));status("静帧已保存："+saved);if(window==saveWindow)message.Text="已保存："+saved;}catch(OperationCanceledException){status("静帧保存已停止。");}catch(Exception ex){status("保存静帧失败："+ex.Message);Diagnostics.Error("filmstrip.save_error",ex);}finally{if(saving!=null){saving.Dispose();saving=null;}busy=false;if(window!=null){save.IsEnabled=snapshot!=null;if(!pinned)closeTimer.Start();}}}
  public void Close(){fadeGeneration++;generation++;opening=false;openTimer.Stop();closeTimer.Stop();if(loading!=null)loading.Cancel();if(saving!=null)saving.Cancel();var old=window;window=null;if(old!=null)old.Close();}
 }
